hosshiiBlockEdit:
function hosshiiBlockEdit() {
  window.hosshiiCheckEntitlementClock?.();
  if (window.hosshiiReadOnly !== true) return false;
  // 期限切れの案内は各画面の上部に常設。入力欄に重なる通知は出さない。
  if (typeof hosshiiSyncExpiredUI === 'function') hosshiiSyncExpiredUI();
  return true;
}

hosshiiCloudBackupSave:
async function hosshiiCloudBackupSave(event) {
  if (event) event.preventDefault();
  if (hosshiiCloudBackupBusy) return;
  if (hosshiiBlockEdit()) return;
  if (storageWriteBlocked) { showStorageSafetyWarning(); return; }
  hosshiiCloudBackupBusy = true;
  const backupButton = event?.currentTarget;
  const oldButtonText = backupButton?.textContent;
  if (backupButton) { backupButton.disabled = true; backupButton.textContent = '保存中…'; }
  try {
    if (window.hosshiiReadOnly !== true) syncSettingsFormToConfig(currentSettingsJobKey);
    const backupData = prelaunchBackup();

    await hosshiiBackupRequest('save', backupData);
    localStorage.setItem('mybasket_last_backup', String(Date.now()));
    showAlertModal('バックアップをSupabaseに保存しました\n同じLINEアカウントで復元できます♡');
  } catch (err) {
    console.error('クラウドバックアップ保存エラー', err);
    showAlertModal('バックアップを保存できませんでした。\n' + (err.name === 'AbortError' ? '通信がタイムアウトしました。' : err.message));
  } finally {
    hosshiiCloudBackupBusy = false;
    if (backupButton) { backupButton.disabled = false; backupButton.textContent = oldButtonText; }
  }
}

hosshiiCloudBackupLoad:
async function hosshiiCloudBackupLoad(event) {
  if (event) event.preventDefault();
  if (hosshiiCloudBackupBusy) return;
  if (hosshiiBlockEdit()) return;
  if (storageWriteBlocked) { showStorageSafetyWarning(); return; }
  hosshiiCloudBackupBusy = true;
  const backupButton = event?.currentTarget;
  const oldButtonText = backupButton?.textContent;
  if (backupButton) { backupButton.disabled = true; backupButton.textContent = '確認中…'; }
  try {
    const data = await hosshiiBackupRequest('load');
    if (!data.backupData || typeof data.backupData !== 'object') throw new Error('保存データを読み取れませんでした。');
    // 既存の確認ダイアログ、検証、ローカル保存とロールバック処理を再利用する。
    processBackupText(JSON.stringify(data.backupData), null);
  } catch (err) {
    console.error('クラウドバックアップ復元エラー', err);
    showAlertModal('バックアップを読み込めませんでした。\n' + (err.name === 'AbortError' ? '通信がタイムアウトしました。' : err.message));
  } finally {
    hosshiiCloudBackupBusy = false;
    if (backupButton) { backupButton.disabled = false; backupButton.textContent = oldButtonText; }
  }
}

exportAppData:
function exportAppData(event) {
  if (event) event.preventDefault();
  if (storageWriteBlocked) { showStorageSafetyWarning(); return; }
  if (window.hosshiiReadOnly !== true) syncSettingsFormToConfig(currentSettingsJobKey);
  const payload = prelaunchBackup();

  const json = JSON.stringify(payload, null, 2);
  const filename = `maishift_backup_${formatDateKey(new Date()).replace(/-/g, '')}.json`;
  const blob = new Blob([json], {type:'application/json'});
  const file = new File([blob], filename, {type:'application/json'});
  let area = document.getElementById('hosshiiBackupDownloadArea');
  if (!area) {
    area = document.createElement('div');
    area.id = 'hosshiiBackupDownloadArea';
    area.style.cssText = 'margin-top:10px;padding:12px;border:1px solid #e9bd9b;border-radius:12px;background:#fff9fa;color:#881337;font-size:13px;line-height:1.7;text-align:center;';
    document.getElementById('importFileInput')?.parentElement?.appendChild(area);
  }
  if (window.hosshiiBackupObjectUrl) URL.revokeObjectURL(window.hosshiiBackupObjectUrl);
  const url = URL.createObjectURL(blob);
  window.hosshiiBackupObjectUrl = url;
  area.replaceChildren();
  const msg = document.createElement('div');
  msg.setAttribute('role','status');
  msg.textContent = 'バックアップを作成しました。保存方法を選んでね♡（まだ保存完了ではありません）';
  area.appendChild(msg);
  const buttonStyle = 'display:block;width:100%;margin:8px auto;padding:10px;border:1px solid #e9bd9b;border-radius:8px;color:#881337;background:white;font-weight:bold;';
  const makeButton = (label) => {
    const btn = document.createElement('button');
    btn.type = 'button'; btn.textContent = label; btn.style.cssText = buttonStyle;
    area.appendChild(btn); return btn;
  };
  // 共有可能な環境では、Androidの「ファイルに保存」等を選べる。
  {
    const shareBtn = makeButton('📤 共有して保存');
    shareBtn.addEventListener('click', async () => {
      try {
        if (!navigator.share) {
          msg.textContent = 'このLINE画面では共有機能を利用できません。コピーしてメモに保存してね。';
          return;
        }
        if (navigator.canShare && navigator.canShare({files:[file]})) {
          await navigator.share({files:[file], title:'シフトアプリのバックアップ'});
        } else {
          await navigator.share({title:'シフトアプリのバックアップ', text:json});
        }
        msg.textContent = '共有先に保存されたか確認してね♡（保存完了は自動確認できません）';
      } catch (err) {
        if (err && err.name === 'AbortError') return;
        msg.textContent = 'このLINE画面では共有できませんでした。ほかの方法を試してね。';
      }
    });
  }
  // 保存先選択 API があるブラウザでは、実際に保存完了するまで成功扱いしない。
  // LINE 内 WebView など非対応環境では、無反応のリンクを出さず代替手段を案内。
  const saveBtn = makeButton('⬇️ 端末にファイル保存');
  saveBtn.addEventListener('click', async () => {
    if (typeof window.showSaveFilePicker === 'function') {
      try {
        const handle = await window.showSaveFilePicker({
          suggestedName: filename,
          types: [{description:'シフトアプリのバックアップ', accept:{'application/json':['.json']}}]
        });
        const writable = await handle.createWritable();
        await writable.write(blob);
        await writable.close();
        try {localStorage.setItem('mybasket_last_backup', String(Date.now()));} catch (_) {}
        msg.textContent = 'バックアップファイルを保存しました♡ 保存先を確認してね。';
        return;
      } catch (err) {
        if (err && err.name === 'AbortError') {msg.textContent = '保存をキャンセルしました。'; return;}
        console.warn('バックアップの保存に失敗',err);
        msg.textContent = 'ファイルを保存できませんでした。別の方法を選んでね。';
        return;
      }
    }
    msg.textContent = 'このLINE画面では端末へのファイル保存に対応していません。共有またはコピーで保存してね。';
  });
  const copyBtn = makeButton('📋 バックアップ内容をコピー');
  const selectBtn = makeButton('📝 内容を表示して選択');
  const help = document.createElement('div');
  help.textContent = 'LINE内でファイル保存に対応していない場合があります。その場合は「バックアップ内容をコピー」でメモ等に保存できます。保存を確認するまでアプリのデータを消さないでね。';
  help.style.cssText = 'font-size:12px;text-align:left;margin-top:6px;';
  area.appendChild(help);
  const backupText = document.createElement('textarea');
  backupText.value = json;
  backupText.readOnly = true;
  backupText.setAttribute('aria-label','バックアップデータ（長押しまたは選択ボタンでコピー）');
  backupText.style.cssText = 'display:none;width:100%;height:150px;margin-top:8px;font-size:14px;line-height:1.5;color:#292524;background:white;border:1px solid #e9bd9b;padding:8px;user-select:text;-webkit-user-select:text;touch-action:auto;';
  area.appendChild(backupText);
  const pasteTitle = document.createElement('div');
  pasteTitle.textContent = 'コピーしたバックアップを読み込む（無料期間中のみ）';
  pasteTitle.style.cssText = 'margin-top:14px;font-size:13px;font-weight:bold;text-align:left;';
  area.appendChild(pasteTitle);
  const pasteInput = document.createElement('textarea');
  pasteInput.placeholder = 'メモ等に保存したバックアップ内容をここに貼り付けてね';
  pasteInput.setAttribute('aria-label','バックアップ復元用の貼り付け欄');
  pasteInput.style.cssText = 'display:block;width:100%;height:76px;margin-top:6px;font-size:14px;color:#292524;background:white;border:1px solid #e9bd9b;padding:8px;user-select:text;-webkit-user-select:text;';
  area.appendChild(pasteInput);
  const pasteBtn = makeButton('⬆️ 貼り付けた内容を読み込む');
  pasteBtn.addEventListener('click', () => {
    if (window.hosshiiReadOnly === true) { hosshiiBlockEdit(); return; }
    if (storageWriteBlocked) { showStorageSafetyWarning(); return; }
    const pasted = pasteInput.value.trim();
    if (!pasted) { showAlertModal('バックアップ内容を貼り付けてね♡'); return; }
    processBackupText(pasted, null);
  });
  if (window.hosshiiReadOnly === true) {
    pasteBtn.disabled = true;
    pasteBtn.style.opacity = '0.5';
    pasteInput.disabled = true;
    pasteTitle.textContent = '読み込みは無料期間中のみ利用できます';
  }
  const reveal = () => {backupText.style.display='block'; backupText.focus(); backupText.select(); backupText.setSelectionRange(0,backupText.value.length);};
  selectBtn.addEventListener('click', () => {
    reveal();
    msg.textContent = '文字を選択しました。表示された「コピー」を押してね。コピーが出ない場合は「バックアップ内容をコピー」を試してね。';
  });
  copyBtn.addEventListener('click', async () => {
    reveal();
    let copied = false;
    // execCommandは一部のLINE WebViewでClipboard APIより利用できる。
    try {copied = !!document.execCommand('copy');} catch (_) {}
    if (!copied && navigator.clipboard && navigator.clipboard.writeText) {
      try {await navigator.clipboard.writeText(json); copied = true;} catch (_) {}
    }
    msg.textContent = copied
      ? 'コピー操作ができました。メモに貼り付けられるか確認してね♡'
      : '自動コピーができませんでした。選択した文字を手動でコピーしてね。';
  });
  // 自動ダウンロードは行わない（LINE内で無反応でも成功と誤認しないため）。
}
